"""Assemble the system prompt from template sections.

Section order favours prompt-prefix caching: deploy-stable sections first
(persona/rules, channel rules, acknowledgement), then
episode-stable framework sections (lifecycle tools, optional out-of-scope
handling), then the current date/time, then turn-local skill or routing
content and any pending tool confirmation. The prompt is rebuilt from the
live tracker every orchestrator iteration, so tool availability and phase
position always reflect current state.

State derivation lives in :mod:`rasa.mantle.prompts.state`; this module
only orders the sections and feeds the views into the templates.
"""

from __future__ import annotations

from collections.abc import Mapping
from datetime import datetime
from typing import TYPE_CHECKING, List, Optional, Sequence

from rasa.mantle.config.agent_spec import AgentSpec, resolve_ack_enabled
from rasa.mantle.config.builtin_tool_constraints import (
    BuiltinToolConstraint,
    builtin_tool_enabled,
    knowledge_search_offered,
)
from rasa.mantle.llm.tool_schemas import (
    TOOL_CANCEL,
    TOOL_CANNOT_HELP,
    TOOL_COMPLETE,
    should_offer_complete,
)
from rasa.mantle.prompts import state
from rasa.mantle.prompts.memory_lines import (
    format_memory_prompt_lines,
    partition_prompt_memory_entries,
)
from rasa.mantle.prompts.messages import (
    KEY_ROLE,
    LlmMessage,
    llm_message,
)
from rasa.mantle.prompts.renderer import join_sections, render_template
from rasa.mantle.prompts.templates import (
    ACK_REMINDER_TEMPLATE,
    ACKNOWLEDGEMENT_TEMPLATE,
    ACTIVE_SKILL_TEMPLATE,
    AGENT_HEADER_TEMPLATE,
    CANNED_UTTER_NOTICE_TEMPLATE,
    CHANNEL_RULES_TEMPLATE,
    CURRENT_DATETIME_TEMPLATE,
    KNOWLEDGE_ANSWERING_TEMPLATE,
    LIFECYCLE_TOOLS_TEMPLATE,
    PENDING_TOOL_CONFIRMATION_TEMPLATE,
    PROJECT_TEMPLATE,
    REPHRASE_TASK_TEMPLATE,
    ROUTING_CATALOG_TEMPLATE,
    SCOPE_HANDLING_TEMPLATE,
    SET_FIELDS_FILL_TASK_TEMPLATE,
    SKIPPED_COLLECT_NOTICE_TEMPLATE,
)
from rasa.mantle.skills.skill_retrieval import apply_allowed_target_ids
from rasa.shared.constants import ROLE_SYSTEM, ROLE_USER

if TYPE_CHECKING:
    from rasa.mantle.prompts.constructor import PromptContext
    from rasa.mantle.skills.skill import Skill

_DATETIME_FORMAT = "%Y-%m-%d %H:%M"


def inject_additional_system_prompt(
    messages: List[LlmMessage], content: str
) -> List[LlmMessage]:
    """Insert a system message right after the last user message.

    Returns *messages* unchanged when *content* is empty/whitespace or there
    is no user message to anchor after. Callers build the reminder text; this
    helper only decides placement so the model reads it immediately before
    responding.
    """
    if not content.strip():
        return messages

    last_user_index = next(
        (
            index
            for index in range(len(messages) - 1, -1, -1)
            if messages[index].get(KEY_ROLE) == ROLE_USER
        ),
        None,
    )
    if last_user_index is None:
        return messages

    insert_at = last_user_index + 1
    return [
        *messages[:insert_at],
        llm_message(ROLE_SYSTEM, content),
        *messages[insert_at:],
    ]


def inject_ack_reminder(
    messages: List[LlmMessage], agent: AgentSpec
) -> List[LlmMessage]:
    """Insert a short ack reminder right after the last user message.

    Mirrors the POC ``inject_ack_reminder``: a system message reinforcing the
    tool-call acknowledgement is placed immediately after the user's request so
    it is the last thing the model reads before responding.  Returns *messages*
    unchanged when there is no user message.  The caller decides when to apply
    this (first LLM iteration only, acknowledgement enabled, no active collect
    step — the ack rule otherwise competes with collect prompting).
    """
    reminder = agent.fillers.reminder.strip() or render_template(ACK_REMINDER_TEMPLATE)
    return inject_additional_system_prompt(messages, reminder)


def skipped_collect_reminder(
    skipped_collects: Sequence[state.SkippedCollectView],
) -> str:
    """Same-turn reminder that collects were skipped because they are already set.

    Empty when nothing was skipped. Callers append this after history so it
    sits after in-turn tool results. The active-skill section embeds the same
    template text when a skill is on the stack.
    """
    if not skipped_collects:
        return ""
    return render_template(
        SKIPPED_COLLECT_NOTICE_TEMPLATE, skipped_collects=skipped_collects
    )


def canned_utter_reminder() -> str:
    """Return the reminder that prevents repeating a delivered canned reply."""
    return render_template(CANNED_UTTER_NOTICE_TEMPLATE)


def build_system_prompt(
    context: "PromptContext", now: Optional[datetime] = None
) -> str:
    """Build the full per-iteration system prompt.

    Args:
        context: Per-iteration prompt inputs (live tracker, bootstrap, current
            turn incl. channel modality).
        now: Override for the rendered date/time (deterministic tests).
    """
    agent = context.bootstrap.agent
    catalog = context.bootstrap.skill_catalog
    active = state.active_skill_view(
        context.tracker,
        catalog,
        context.memory_values,
        memory_cleared_by_correction=context.memory_cleared_by_correction,
        correct_tool_available=context.correct_tool_available,
        memory_entries=context.memory_entries,
        pending_tool_confirmation=context.pending_tool_confirmation,
        skipped_collects=context.skipped_collects,
    )

    active_target_id = state.active_target_id(context.tracker)
    paused_block_ids = state.paused_ordered_block_target_ids(context.tracker, catalog)
    activate_available = context.activate_tool_available and bool(
        apply_allowed_target_ids(
            catalog.get_startable_candidate_target_ids(
                context.memory_values,
                active_target_id=active_target_id,
                paused_block_ids=paused_block_ids,
            ),
            context.allowed_target_ids,
        )
    )

    sections: List[str] = [
        _persona_rules_section(agent),
        _channel_rules_section(agent, context.turn.is_voice),
    ]
    # First LLM call only. Later iterations omit it so the model is not told
    # to acknowledge again mid-turn.
    ack_enabled = (
        resolve_ack_enabled(agent.fillers, is_voice=context.turn.is_voice)
        and context.is_first_llm_iteration
    )
    if ack_enabled:
        sections.append(_acknowledgement_section(agent))
    constraints = agent.orchestrator.tool_constraints
    # When search_knowledge is offered the prompt steers informational questions
    # to it (and away from the unsupported-request handler).
    knowledge_available = knowledge_search_offered(
        constraints, context.bootstrap.references_index is not None
    )
    # Mirror the cannot_help tool gate in build_llm_tools_for_turn: with a knowledge
    # base configured the tool is withheld until a search has run this turn (so
    # the model cannot decline before the context is possibly complete); with no
    # knowledge base it is offered from the first round. All cannot_help guidance
    # must track this flag so the prompt never advertises a tool that is not
    # currently offered.
    cannot_help_offered = builtin_tool_enabled(constraints, TOOL_CANNOT_HELP) and (
        context.knowledge_searched or not knowledge_available
    )
    # After a knowledge search this turn the lifecycle tools are trimmed to
    # activate + search_knowledge (see build_llm_tools_for_turn), so suppress the
    # complete / cancel guidance to match the offered tool set.
    has_active_skill = active is not None and not context.knowledge_searched
    complete_available = (
        has_active_skill
        and should_offer_complete(catalog, active_target_id)
        and builtin_tool_enabled(constraints, TOOL_COMPLETE)
    )
    cancel_available = has_active_skill and builtin_tool_enabled(
        constraints, TOOL_CANCEL
    )
    invoke_when = _invoke_when_by_tool(constraints)
    sections.append(
        _lifecycle_tools_section(
            context,
            has_active_skill,
            knowledge_available,
            cannot_help_offered,
            activate_available,
            context.listen_available,
            complete_available,
            cancel_available,
            context.set_fields_available,
            invoke_when,
            ack_enabled,
        )
    )

    # The scope_handling section is static cannot_help guidance, so it renders
    # only when the handler is not already active (see should_render_scope_handling)
    # and while the tool is actually offered — suppressed when cannot_help is
    # withheld (KB configured, no search yet this turn). A builder's invoke_when
    # for cannot_help replaces this section along with that tool's when-lines.
    if (
        state.should_render_scope_handling(
            catalog, state.active_target_id(context.tracker)
        )
        and cannot_help_offered
        and TOOL_CANNOT_HELP not in invoke_when
    ):
        sections.append(
            render_template(
                SCOPE_HANDLING_TEMPLATE,
                knowledge_available=knowledge_available,
            )
        )

    sections.append(_datetime_section(now))
    sections.extend(_project_section(context))

    if active is not None:
        # Once search_knowledge has run this turn, render the compact
        # answer-from-knowledge section instead of the full active-skill section,
        # so the grounded answer does not also re-drive the skill's steps.
        active_skill_template = (
            KNOWLEDGE_ANSWERING_TEMPLATE
            if context.knowledge_searched
            else ACTIVE_SKILL_TEMPLATE
        )
        sections.append(
            render_template(
                active_skill_template,
                skill=active,
                skipped_collect_notice=skipped_collect_reminder(
                    active.skipped_collects
                ),
                set_fields_available=context.set_fields_available,
                invoke_when=invoke_when,
            )
        )
    else:
        sections.append(_routing_catalog_section(context, agent, invoke_when))

    # Advertise resolve whenever the tool is offered (mirrors build_llm_tools_for_turn).
    # Kept outside the knowledge-answering swap so a clarifying search during
    # requires_confirmation does not strand the pending gate.
    if context.pending_tool_confirmation is not None:
        sections.append(
            render_template(
                PENDING_TOOL_CONFIRMATION_TEMPLATE,
                pending_tool_confirmation=context.pending_tool_confirmation,
            )
        )

    return join_sections(sections)


def build_rephrase_system_prompt(
    context: "PromptContext", now: Optional[datetime] = None
) -> str:
    """Build the minimal system prompt for a rephrase-only LLM call.

    Persona and channel rules keep the rewording on-brand; skill state, tools,
    and acknowledgement are omitted because no tool calls are allowed in
    rephrase mode.
    """
    agent = context.bootstrap.agent
    sections = [
        _persona_rules_section(agent),
        render_template(REPHRASE_TASK_TEMPLATE),
        _channel_rules_section(agent, context.turn.is_voice),
        _datetime_section(now),
    ]
    return join_sections(sections)


def build_set_fields_fill_system_prompt(
    now: Optional[datetime] = None,
) -> str:
    """Build the minimal system prompt for a silent memory extraction call."""
    return join_sections(
        [
            render_template(SET_FIELDS_FILL_TASK_TEMPLATE),
            _datetime_section(now),
        ]
    )


def _persona_rules_section(agent: AgentSpec) -> str:
    return render_template(
        AGENT_HEADER_TEMPLATE,
        persona=agent.persona.strip(),
        rules=agent.rules,
    )


def _datetime_section(now: Optional[datetime]) -> str:
    current_datetime = (now or datetime.now()).strftime(_DATETIME_FORMAT)
    return render_template(
        CURRENT_DATETIME_TEMPLATE,
        current_datetime=current_datetime,
    )


def _project_section(context: "PromptContext") -> List[str]:
    """Render the ``### Project Memory`` prompt section when any project field is set.

    Skill-scoped entries are ignored here; they stay in ``### Memory:``. Unset
    and empty project maps produce no section so routing and active-skill
    prompts share the same heading only when there is something to show.

    Args:
        context: Per-iteration prompt inputs, including ``memory_entries``.

    Returns:
        A one-element list with the rendered section, or an empty list when
        no project field has a value.
    """
    project_entries, _skill_entries = partition_prompt_memory_entries(
        context.memory_entries
    )
    project_lines = format_memory_prompt_lines(project_entries)
    if not project_lines:
        return []
    return [render_template(PROJECT_TEMPLATE, project_lines=project_lines)]


def _channel_rules_section(agent: AgentSpec, is_voice: bool) -> str:
    return render_template(
        CHANNEL_RULES_TEMPLATE,
        is_voice=is_voice,
        voice_rules=agent.orchestrator.voice_rules.strip(),
        text_rules=agent.orchestrator.text_rules.strip(),
    )


def _acknowledgement_section(agent: AgentSpec) -> str:
    return render_template(
        ACKNOWLEDGEMENT_TEMPLATE,
        ack_rule=agent.fillers.instructions.strip(),
        ack_examples=agent.fillers.examples,
    )


def _invoke_when_by_tool(
    constraints: Mapping[str, BuiltinToolConstraint],
) -> dict[str, str]:
    """Builder when-text for tools that are still on.

    A turned-off tool keeps its text on the spec and does not render it.
    """
    rendered: dict[str, str] = {}
    for tool_name, constraint in constraints.items():
        if constraint.enabled and constraint.invoke_when:
            rendered[tool_name] = constraint.invoke_when
    return rendered


def _lifecycle_tools_section(
    context: "PromptContext",
    has_active_skill: bool,
    knowledge_available: bool,
    cannot_help_available: bool,
    activate_available: bool,
    listen_available: bool,
    complete_available: bool,
    cancel_available: bool,
    set_fields_available: bool,
    invoke_when: Mapping[str, str],
    ack_enabled: bool,
) -> str:
    catalog = context.bootstrap.skill_catalog
    active_target_id = state.active_target_id(context.tracker)
    active_skill = (
        catalog.owning_skill_for_target_id(active_target_id)
        if active_target_id
        else None
    )
    active_skill_id = active_skill.id if active_skill else None
    memory = context.memory_values
    referenced = state.referenced_targets(
        catalog,
        memory,
        active_skill_id=active_skill_id,
        allowed_target_ids=context.allowed_target_ids,
    )
    others = state.other_targets(
        catalog,
        active_target_id,
        memory,
        exclude_target_ids={entry.skill_id for entry in referenced},
        allowed_target_ids=context.allowed_target_ids,
    )
    return render_template(
        LIFECYCLE_TOOLS_TEMPLATE,
        has_active_skill=has_active_skill,
        complete_available=complete_available,
        cancel_available=cancel_available,
        referenced_skills=referenced,
        other_skills=others,
        knowledge_available=knowledge_available,
        knowledge_answering_instructions=_knowledge_answering_instructions(
            context.bootstrap.agent, active_skill
        ),
        cannot_help_available=cannot_help_available,
        activate_available=activate_available,
        listen_available=listen_available,
        set_fields_available=set_fields_available,
        invoke_when=invoke_when,
        ack_enabled=ack_enabled,
    )


def _knowledge_answering_instructions(
    agent: AgentSpec, active_skill: Optional["Skill"]
) -> str:
    """Return answering text for the paragraph after the search bullet.

    An active skill's text replaces the agent's. Empty when both are blank,
    so the built-in instruction in the bullet is the only how-guidance.
    """
    if active_skill is not None and active_skill.knowledge_answering_instructions:
        skill_text = active_skill.knowledge_answering_instructions.strip()
        if skill_text:
            return skill_text
    return agent.knowledge_answering.instructions.strip()


def _routing_catalog_section(
    context: "PromptContext",
    agent: AgentSpec,
    invoke_when: Mapping[str, str],
) -> str:
    catalog_view = state.routing_catalog_view(
        context.bootstrap.skill_catalog,
        agent,
        context.memory_values,
        allowed_target_ids=context.allowed_target_ids,
    )
    return render_template(
        ROUTING_CATALOG_TEMPLATE,
        routable_skills=catalog_view.routable_skills,
        before_end=catalog_view.before_end,
        routing_no_active=catalog_view.routing_no_active,
        invoke_when=invoke_when,
    )
